/**
 * D!EMONIC: автоматический пропуск с задержкой.
 *
 * Для категорий с опцией {@link CategorySkipOption.DelayedAutoSkip} оригинальный SponsorBlock
 * ведёт себя как при ручном пропуске (показывает уведомление с кнопкой «Пропустить»),
 * а этот модуль поверх этого показывает на плеере бейдж с обратным отсчётом.
 * Когда отсчёт доходит до нуля, вызывается колбэк, который выполняет обычный пропуск.
 *
 * Отсчёт отменяется, если:
 *  - пользователь кликнул по бейджу;
 *  - видео ушло за пределы сегмента (пользователь перемотал / нажал «Пропустить» в уведомлении);
 *  - видео-элемент пропал со страницы или сменилось видео ({@link cancelDelayedSkip} из resetValues).
 * Пока видео на паузе, отсчёт не идёт.
 */

import { ActionType, CategorySkipOption, SponsorTime } from "../types";
import { getCategorySelection } from "../utils/skipRule";

/** Сколько «тиков» показывает бейдж (5, 4, 3, 2, 1). */
const COUNTDOWN_STEPS = 5;
/** Длительность одного тика, мс. Полная задержка = COUNTDOWN_STEPS * STEP_DURATION_MS. */
const STEP_DURATION_MS = 200;
/** Как часто проверяем состояние видео, мс. */
const TICK_INTERVAL_MS = 50;
/** Допуск при проверке, что видео всё ещё внутри сегмента, сек. */
const RANGE_TOLERANCE_SECONDS = 1;
/** Перематываем на столько секунд раньше конца сегмента, чтобы не пропустить начало контента. */
const PRE_SKIP_SECONDS = 2;

const BADGE_ID = "diemonicDelayedSkipBadge";
const STYLE_ID = "diemonicDelayedSkipStyle";

let activeCountdown: { cancel: () => void } | null = null;

export function log(message: string): void {
    console.log("%c🚫[D!EMONIC SponsorBlock] " + message, "background: #464646b9; color: rgb(255, 46, 143)");
}

/** Нужно ли для сегмента запускать отсчёт. Действует только на обычные (не mute/poi/chapter) сегменты. */
export function isDelayedAutoSkipSegment(segment: SponsorTime | undefined): boolean {
    return !!segment
        && segment.actionType === ActionType.Skip
        && getCategorySelection(segment)?.option === CategorySkipOption.DelayedAutoSkip;
}

/**
 * Возвращает новый skipTime, у которого конец сдвинут на PRE_SKIP_SECONDS раньше.
 * Исходный массив не изменяется (часто это ссылка на segment.segment).
 */
export function withPreSkipOffset(skipTime: number[], segments: SponsorTime[]): number[] {
    const [start, end] = skipTime;
    if (segments[0]?.actionType !== ActionType.Skip
            || !Number.isFinite(start) || !Number.isFinite(end)
            || end - PRE_SKIP_SECONDS <= start) {
        return skipTime;
    }

    return [start, end - PRE_SKIP_SECONDS];
}

export function cancelDelayedSkip(reason?: string): void {
    if (!activeCountdown) return;

    if (reason) log("Отсчёт отменён: " + reason);
    activeCountdown.cancel();
    activeCountdown = null;
}

/**
 * Запускает отсчёт для сегмента. Предыдущий отсчёт (если был) отменяется.
 * @param onSkip вызывается, когда отсчёт закончился и видео всё ещё внутри сегмента
 */
export function startDelayedSkip(video: HTMLVideoElement, segment: SponsorTime, onSkip: () => void): void {
    cancelDelayedSkip();

    const [start, end] = segment.segment;
    if (!video || !(end > start)) return;

    const totalMs = COUNTDOWN_STEPS * STEP_DURATION_MS;
    let elapsedMs = 0;
    let lastTick = performance.now();

    const badge = createBadge(video, () => cancelDelayedSkip("пользователь нажал на бейдж"));

    const tick = () => {
        const now = performance.now();
        const delta = now - lastTick;
        lastTick = now;

        if (!video.isConnected) {
            cancelDelayedSkip("видео пропало со страницы");
            return;
        }

        const time = video.currentTime;
        if (time < start - RANGE_TOLERANCE_SECONDS || time > end + RANGE_TOLERANCE_SECONDS) {
            cancelDelayedSkip(`видео вне сегмента (${time.toFixed(1)} не в [${start.toFixed(1)}, ${end.toFixed(1)}])`);
            return;
        }

        if (!video.paused && !video.seeking) {
            elapsedMs += delta;
        }

        if (elapsedMs >= totalMs) {
            cancelDelayedSkip();
            log(`Пропускаем сегмент ${segment.category} [${start.toFixed(1)} - ${end.toFixed(1)}]`);
            onSkip();
            return;
        }

        badge.textContent = String(Math.ceil((totalMs - elapsedMs) / STEP_DURATION_MS));
    };

    const timer = window.setInterval(tick, TICK_INTERVAL_MS);
    activeCountdown = {
        cancel: () => {
            window.clearInterval(timer);
            badge.remove();
        }
    };

    log(`Запущен отсчёт для сегмента ${segment.category} [${start.toFixed(1)} - ${end.toFixed(1)}]`);
    tick();
}

function createBadge(video: HTMLVideoElement, onClick: () => void): HTMLElement {
    injectStyle();
    document.getElementById(BADGE_ID)?.remove();

    // Внутри плеера бейдж виден и в полноэкранном режиме
    const container = video.closest(".html5-video-player, .video-js") as HTMLElement | null;

    const badge = document.createElement("div");
    badge.id = BADGE_ID;
    badge.title = chrome.i18n.getMessage("diemonicCancelDelayedSkip") || "Cancel skip";
    if (!container) badge.classList.add("diemonicFixed");

    // Не даём клику дойти до плеера (иначе YouTube поставит видео на паузу)
    for (const eventName of ["mousedown", "mouseup", "pointerdown", "pointerup", "dblclick"]) {
        badge.addEventListener(eventName, (e) => e.stopPropagation());
    }
    badge.addEventListener("click", (e) => {
        e.stopPropagation();
        e.preventDefault();
        onClick();
    });

    (container ?? document.body).appendChild(badge);
    return badge;
}

function injectStyle(): void {
    if (document.getElementById(STYLE_ID)) return;

    const style = document.createElement("style");
    style.id = STYLE_ID;
    style.textContent = `
        #${BADGE_ID} {
            position: absolute;
            right: 25px;
            bottom: 70px;
            width: 76px;
            height: 90px;
            line-height: 90px;
            box-sizing: border-box;
            font-family: Roboto, Arial, sans-serif;
            font-size: 79px;
            color: #ffffff;
            text-align: center;
            background-color: rgb(0 0 0 / 60%);
            border: 2px solid rgb(110 110 110);
            border-radius: 18px;
            cursor: pointer;
            user-select: none;
            z-index: 1000;
            transition: transform 0.1s, background-color 0.1s, border-color 0.1s;
        }
        #${BADGE_ID}.diemonicFixed {
            position: fixed;
            bottom: 25px;
        }
        #${BADGE_ID}:hover {
            background-color: rgb(33 33 33 / 90%);
            border-color: rgb(221 28 28);
            transform: scale(1.1);
        }
    `;
    (document.head ?? document.documentElement).appendChild(style);
}
